-- SOLO01 Chặng 2 · đồng bộ BẢN NHẠC CHUẨN "Con Đường Xưa em Đi" v5-2026-11-17 vào class_lesson_content (buổi 9, 10, 11, 13, 14, 15, 16).
-- Buổi 12 KHÔNG đụng (không có bản nhạc đổi). Không đổi status/quyền/khoá/bài trả/đáp án — chỉ thay cột blocks.
-- An toàn: (1) bản sao lưu trong tva_private (RLS bật, không lộ ra API); (2) mỗi buổi chỉ cập nhật nếu md5(blocks) ĐÚNG như lúc đọc,
-- sai → dừng cả migration; (3) sau cập nhật phải đúng 1 dòng/buổi. Hoàn tác: db/solo01_chang2_cdx_v5_sync_rollback.sql
create table if not exists tva_private.class_lesson_content_bak_20261117 (like public.class_lesson_content);
alter table tva_private.class_lesson_content_bak_20261117 enable row level security;
alter table tva_private.class_lesson_content_bak_20261117 add column if not exists backed_up_at timestamptz not null default now();
insert into tva_private.class_lesson_content_bak_20261117 (session_id, event_type, status, blocks, updated_at, updated_by)
  select c.session_id, c.event_type, c.status, c.blocks, c.updated_at, c.updated_by from public.class_lesson_content c
  where c.session_id in ('028adc12-051f-4d23-a514-d85a4aa064a2','0c1d496c-c9b3-49b1-bca7-d4537b0eee2d','14dd9919-5da6-46f1-9772-298833677d8b','eb652678-11b4-4d5e-bac3-be242b551166','cc361627-321f-46b7-9d9c-92ebf7b0ac89','8237b352-ea28-435d-ab7a-016ca23b7aa7','43b28a5e-cf31-4a94-82f3-2bab17b3d3aa')
    and not exists (select 1 from tva_private.class_lesson_content_bak_20261117 b where b.session_id=c.session_id);
do $sync$
declare n int;
begin
  -- Buổi 9
  update public.class_lesson_content set blocks = $j$[{"kind":"recap","title":"Từ Chặng 1 sang Chặng 2","steps":[{"label":"Chặng 1 đã có","items":["Tìm nốt melody trên cần đàn.","Ép ngón i–m, thêm bass đầu tiên.","Slide, luyến, xếp ngón."]},{"label":"Chặng 2 xây thêm","items":["Một quy trình trọn vẹn dựng Solo Bolero — mỗi buổi là một bước.","Bài mẫu xuyên suốt 8 buổi: Con Đường Xưa em Đi."]}],"message":"Bài mẫu được phối ở QUÃNG 8 CAO: giai điệu nằm trên dây 1 (dây 2 khi nốt thấp) và ở ngăn cao hơn so với bản gốc, để chừa chỗ bên dưới cho Bass và hợp âm. Lộ trình 8 buổi: Melody & kỹ thuật → Bass → Xếp ngón → Hợp âm bấm tắt → Chèn hợp âm theo công thức Bolero → Ghép Bass + hợp âm cho điệp khúc → Tự dựng → Tổng kết & biểu diễn. Buổi này là bước đầu: có một melody sạch, rồi làm nó biết hát."},{"kind":"objectives","title":"Cuối buổi, bạn làm được","items":["Đọc đúng melody ô 1–8 của Con Đường Xưa em Đi: cao độ, trường độ, nốt chấm, chùm ba.","Phân biệt và thực hiện được 5 kỹ thuật: Hammer-on, Pull-off, Vibrato, Slide, Bend.","Biết kỹ thuật nào hợp với kiểu nốt nào (nốt liền bậc, nốt dài, nốt đổi ngăn…).","Hiểu kỹ thuật là LỰA CHỌN diễn tấu của người chơi, không phải luật bắt buộc.","⭐ QUAN TRỌNG NHẤT — Chọn một kỹ thuật cho một chỗ trong bài và nói được vì sao."]},{"kind":"note","title":"Nhịp 1 · Đọc melody Con Đường Xưa em Đi","text":"Phần 1 — Làm ngay: đàn chậm ô 1–8 theo bản nhạc. Kết thúc nhịp: Bài trả 9.1 (trắc nghiệm)."},{"kind":"score","subtitle":"Phần 1 — Làm ngay","title":"Ô 1–8: melody gốc, chưa kỹ thuật","lead":"Giọng La thứ (Am), nhịp 4/4, bản phối nâng một quãng 8. Tay trái ghi theo VỊ TRÍ: trong một vị trí, ngón 1 giữ ngăn đầu của vị trí, ngón 2 giữ ngăn kế, ngón 3 ngăn kế nữa, ngón 4 ngăn cuối (xem kỹ ở Buổi 3). Dây buông không ghi ngón. Dây 1 là dây e cao, dây 6 là dây E trầm.","tempo":"Tempo: ♩ = 60","tex":"\\ts 4 4\n.\nr.4 0.1.4 1.2{lf 2}.4{tu 3} 3.1{lf 4 slur s1}.8{tu 3} 5.1{lf 2 slur s1}.8{tu 3} 5.1{lf 2}.4{tu 3} |\n5.1{lf 2 ch \"Am\"}.4{d} 0.1.8 5.1{lf 2}.8 8.1{lf 5}.4 0.1.8 |\n3.2{lf 2 ch \"Dm\"}.4{d} 5.2{lf 4 slur s2}.16 3.2{lf 2 slur s2}.16 1.2{lf 2}.4{tu 3} 3.2{lf 2}.4{tu 3} 0.1{slur s3}.8{tu 3} 5.1{lf 4 slur s3}.8{tu 3} |\n0.1{ch \"Am\"}.1 |\n0.1{t}.4 0.1.4 2.3{lf 3}.4{tu 3} 1.2{lf 2 slur s4}.8{tu 3} 3.2{lf 4 slur s4}.8{tu 3} 3.2{lf 4}.4{tu 3} |\n3.2{lf 4 ch \"Dm\"}.4{d} 0.1.8 3.2{lf 4}.8 1.2{lf 2}.4 1.1{lf 2}.8 |\n0.1{ch \"Am\"}.4{d} 0.1{slur s5}.16 1.1{lf 2 slur s5}.16 0.1.4{tu 3} 5.1{lf 2}.4{tu 3} 8.1{lf 5}.4{tu 3} |\n7.1{lf 4 ch \"E\"}.1 |","marks":[{"at":"Ô 1","text":"ô vào: nghỉ một phách, rồi 5 nốt: hai nốt đen, sau đó chùm ba (ba nốt chia đều trong hai phách). Cung luyến (Slur) nối Sol → La, hai nốt khác cao độ"},{"at":"Ô 2","text":"nốt đen chấm đầu ô = 1,5 phách"},{"at":"Ô 4","text":"một nốt tròn (4 phách) trên dây 1 BUÔNG — nốt dài đầu tiên của bài, nhưng dây buông nên không rung được (xem Nhịp 2)"},{"at":"Ô 4 → 5","text":"cung nối (Tie): hai nốt Mi CÙNG cao độ nối thành một nốt dài 5 phách — gảy MỘT lần ở ô 4, giữ qua ô 5, không gảy lại (trong TAB nốt thứ hai ghi trong ngoặc)"},{"at":"Ô 3, 5, 7","text":"cung luyến (Slur) nối hai nốt KHÁC cao độ thành một nhóm liền tiếng, không đổi trường độ. Slur là ký hiệu ký âm, chưa nói sẵn là Hammer-on hay Pull-off — kỹ thuật cụ thể do bạn chọn ở Nhịp 3"},{"at":"Ô 8","text":"nốt Si dây 1 ngăn 7, tròn, kéo dài cả ô"}],"guidance":["Đàn từng ô riêng, rồi ghép 2 ô. Đừng đàn cả đoạn khi chưa đều.","Giai điệu nằm ở hai vùng: nốt thấp (dây 2–1, ngăn 1–3) và nốt cao (dây 1, ngăn 5–8; có chỗ lên ngăn 10–12). Chuyển vùng bằng cách dịch cả bàn tay, đừng với ngón.","Mi dây 1 buông xuất hiện nhiều: đó là lúc tay trái được nghỉ để dịch vị trí.","Chưa thêm kỹ thuật vội. Có một melody sạch rồi mới trang trí."]},{"kind":"checkpoint","id":"9.1","title":"Bài trả 9.1 — Đọc melody","required":true,"accepts":["quiz"],"quiz":{"mode":"single","question":"Nốt đầu tiên của ô 2 là nốt đen chấm (La, dây 1 ngăn 5). Trong nhịp 4/4, nốt đen chấm kéo dài bao nhiêu phách?","options":[{"id":"a","text":"1 phách"},{"id":"b","text":"1,5 phách"},{"id":"c","text":"2 phách"},{"id":"d","text":"3 phách"}],"hint":"Dấu chấm cộng thêm MỘT NỬA giá trị của nốt đứng trước nó. Nốt đen = 1 phách."}},{"kind":"note","title":"Nhịp 2 · Năm kỹ thuật diễn tấu","text":"Luyện từng kỹ thuật ở bài tập riêng, rồi tìm chúng trong bài. Kết thúc nhịp: Bài trả 9.2 (trắc nghiệm)."},{"kind":"recap","title":"Năm kỹ thuật — nhìn nhanh","steps":[{"label":"Hammer-on (luyến lên)","items":["Gảy nốt thấp, GÕ ngón khác xuống nốt cao hơn trên cùng dây.","Chỉ gảy một lần."]},{"label":"Pull-off (luyến xuống)","items":["Gảy nốt cao, MÓC ngón ra để nốt thấp hơn vang lên.","Chỉ gảy một lần."]},{"label":"Slide (trượt)","items":["Giữ MỘT ngón, trượt dọc dây từ ngăn này sang ngăn kia.","Nghe cả đường đi giữa hai nốt."]},{"label":"Vibrato (rung)","items":["Làm cao độ của nốt dài dao động nhẹ.","Chỉ làm được trên nốt đang BẤM — dây buông thì không rung được."]},{"label":"Bend (vuốt dây)","items":["Đẩy dây để nâng cao độ liên tục.","Điểm đến thường là nửa cung hoặc một cung."]}],"message":"Hammer-on và Pull-off thuộc nhóm luyến (legato). Slide, Vibrato, Bend biến đổi cao độ bằng tay trái. Cả năm chỉ là cách làm đẹp thêm cho một nốt đã đúng."},{"kind":"score","subtitle":"Bài tập kỹ thuật 01","title":"Hammer-on và Pull-off","lead":"Ba ô nhịp trên dây 1: ngăn 5 ↔ 7, ngăn 5 ↔ 8, rồi dây buông ↔ ngăn 1. Chỉ gảy nốt đầu của mỗi cặp.","tempo":"Tempo: ♩ = 60","tex":"\\ts 4 4\n.\n5.1{lf 2 h}.4 7.1{lf 4}.4 7.1{lf 4 h}.4 5.1{lf 2}.4 |\n5.1{lf 2 h}.4 8.1{lf 5}.4 8.1{lf 5 h}.4 5.1{lf 2}.4 |\n0.1{h}.4 1.1{lf 2}.4 1.1{lf 2 h}.4 0.1.4 |","guidance":["Hammer-on: gõ bằng đầu ngón, sát ngăn phím, dứt khoát — nốt sau phải nghe rõ gần bằng nốt gảy.","Pull-off: móc ngón sang ngang (không chỉ nhấc lên) thì dây mới kêu.","Hai nốt của một cặp luyến dùng HAI NGÓN KHÁC NHAU; slide thì dùng một ngón."]},{"kind":"score","subtitle":"Bài tập kỹ thuật 02","title":"Slide","lead":"Một ngón trượt trên dây 2 (ngăn 1 ↔ ngăn 3) và trên dây 1 (ngăn 5 ↔ ngăn 8).","tempo":"Tempo: ♩ = 60","tex":"\\ts 4 4\n.\n1.2{lf 2 ss}.4 3.2{lf 2}.4 3.2{lf 2 ss}.4 1.2{lf 2}.4 |\n5.1{lf 2 ss}.4 8.1{lf 2}.4 8.1{lf 2 ss}.4 5.1{lf 2}.4 |","guidance":["Giữ ngón ép nhẹ trên dây suốt đường trượt, đừng nhấc ra giữa chừng.","Gảy nốt đầu một lần; nốt đến vang lên nhờ đường trượt.","Trượt quá ngắn nghe như luyến; trượt đủ dài mới nghe thấy \"đường đi\"."]},{"kind":"score","subtitle":"Bài tập kỹ thuật 03","title":"Vibrato","lead":"Hai nốt dài: Si (dây 1 ngăn 7) và La (dây 1 ngăn 5). Rung đều, nhẹ, không làm nốt lệch tông.","tempo":"Tempo: ♩ = 60","tex":"\\ts 4 4\n.\n7.1{lf 4 v}.2 7.1{lf 4 v}.2 |\n5.1{lf 2 v}.1 |","guidance":["Cách phổ biến: xoay nhẹ cổ tay để kéo – đẩy dây; mỗi người có thói quen riêng.","Chỉ rung khi nốt đủ dài. Nốt ngắn mà rung nghe run và mờ.","Nốt dây buông (như Mi dây 1 buông ở ô 4) không rung được bằng tay trái — muốn rung phải bấm cùng cao độ ở chỗ khác (Mi cũng có ở dây 2 ngăn 5). Nốt tròn Si ở ô 8 là nốt bấm nên rung được."]},{"kind":"score","subtitle":"Bài tập kỹ thuật 04","title":"Bend","lead":"La (dây 1 ngăn 5) vuốt lên một cung chạm Si (dây 1 ngăn 7). Ô 1: bend đến đích. Ô 2: bend rồi nhả về. Ô 3: đàn nốt Si thật (ngăn 7) để so cao độ.","tempo":"Tempo: ♩ = 60","tex":"\\ts 4 4\n.\n5.1{lf 4 b (0 4)}.2 r.2 |\n5.1{lf 4 b (0 4 0)}.2 r.2 |\n5.1{lf 4}.4 7.1{lf 4}.4 5.1{lf 4}.2 |","guidance":["Bend bằng ngón 3 ở ngăn 5, đặt ngón 1 và 2 ở ngăn 3 và 4 phía sau trợ lực.","Đẩy dây bằng sức cả cổ tay, không chỉ ngón. Nghe đích đến rồi mới chỉnh.","Mục tiêu là cao độ đúng: thiếu nghe như hụt, thừa nghe như lệch nốt."]},{"kind":"checkpoint","id":"9.2","title":"Bài trả 9.2 — Kỹ thuật diễn tấu","required":true,"accepts":["quiz"],"quiz":{"mode":"single","question":"Nốt nào dưới đây KHÔNG thể rung (vibrato) bằng tay trái?","options":[{"id":"a","text":"Si — dây 1 ngăn 7 (nốt tròn ô 8)"},{"id":"b","text":"Mi — dây 1 buông (nốt tròn ô 4)"},{"id":"c","text":"La — dây 1 ngăn 5 (nốt tròn ô 16, nối sang ô 17)"},{"id":"d","text":"Rê — dây 1 ngăn 10 (ô 18)"}],"hint":"Vibrato làm đổi cao độ nhờ tay trái ép dây. Nốt nào không có ngón nào đang ép dây?"}},{"kind":"note","title":"Nhịp 3 · Chọn kỹ thuật cho bài","text":"Tìm những chỗ trong bài có thể thêm kỹ thuật, chọn một, đàn và thu video. Kết thúc nhịp: Bài trả 9.3 (video + giải thích)."},{"kind":"layers","title":"Cùng một ô, hai cách đàn","lead":"Ô 18 có Mi → Rê liền nhau trên dây 1 (ngăn 12 → ngăn 10). Có thể gảy từng nốt, hoặc gảy Mi rồi luyến xuống Rê bằng Pull-off. Cả hai đều đúng, nghe khác nhau.","layers":[{"label":"Cách 1","what":"Gảy từng nốt — rõ ràng, tách bạch.","tex":"\\ts 4 4\n.\n5.1{ch \"Am\"}.2 5.1.4{tu 3} 12.1.4{tu 3} 10.1.4{tu 3} |"},{"label":"Cách 2","what":"Gảy Mi, Pull-off xuống Rê — hai nốt dính liền, mềm hơn.","tex":"\\ts 4 4\n.\n5.1{ch \"Am\"}.2 5.1.4{tu 3} 12.1{lf 5 h}.4{tu 3} 10.1{lf 3}.4{tu 3} |","current":true}],"note":"Thầy chấm bạn nói được vì sao chọn, không chấm bạn chọn giống Thầy."},{"kind":"repertoire","title":"Những chỗ trong bài có thể thêm kỹ thuật","candidates":["Con Đường Xưa em Đi — chọn một chỗ, tự quyết định kỹ thuật"],"status":"ready","pieces":[{"title":"Ô 7 — Mi → Fa (dây 1, buông → ngăn 1)","composer":"Châu Kỳ & Hồ Đình Phương","note":"Gợi ý: Hammer-on từ dây buông lên Fa. Hai nốt rất ngắn (nốt 16), luyến cho gọn.","barsPerRow":1,"tex":"\\ts 4 4\n.\n0.1{ch \"Am\"}.4{d} 0.1{h}.16 1.1{lf 2}.16 0.1.4{tu 3} 5.1.4{tu 3} 8.1.4{tu 3} |"},{"title":"Ô 8 — nốt Si dài 4 phách (dây 1 ngăn 7)","composer":"Châu Kỳ & Hồ Đình Phương","note":"Gợi ý: Vibrato. Nốt tròn bấm ở ngăn 7 — chỗ rung rõ nhất của đoạn đầu. (Nốt tròn ô 4 là Mi dây buông nên không rung được.)","barsPerRow":1,"tex":"\\ts 4 4\n.\n7.1{lf 4 v ch \"E\"}.1 |"},{"title":"Ô 9 — Sol♯ → La (dây 1, ngăn 4 → ngăn 5)","composer":"Châu Kỳ & Hồ Đình Phương","note":"Gợi ý: Slide một ngón từ ngăn 4 sang ngăn 5. Ô 9 nằm ngoài ô 1–8, nhưng gặp lại ở ô 33.","barsPerRow":1,"tex":"\\ts 4 4\n.\n7.1{t}.4 7.1.4 0.1.4{tu 3} 4.1{lf 2 ss}.8{tu 3} 5.1{lf 2}.8{tu 3} 5.1.4{tu 3} |"},{"title":"Ô 18 — Mi → Rê (dây 1, ngăn 12 → ngăn 10)","composer":"Châu Kỳ & Hồ Đình Phương","note":"Gợi ý: Pull-off từ Mi xuống Rê, hai ngón khác nhau (ngón 4 → ngón 2). Cả cụm ba nốt chùm ba vẫn phải đều.","barsPerRow":1,"tex":"\\ts 4 4\n.\n5.1{ch \"Am\"}.2 5.1.4{tu 3} 12.1{lf 5 h}.4{tu 3} 10.1{lf 3}.4{tu 3} |"}],"annotationTypes":["Kỹ thuật bạn chọn","Ô nhịp","Ngón tay trái","Lý do chọn","Ghi chú của giáo viên"]},{"kind":"checkpoint","id":"9.3","title":"Bài trả 9.3 — Kỹ thuật tôi chọn","prompt":"Chơi ô 1–8 Con Đường Xưa em Đi, thêm MỘT kỹ thuật (Hammer-on, Pull-off, Vibrato hoặc Slide) vào một chỗ bạn chọn. Không cần cả đoạn hoàn hảo. Viết ngắn: ‘Tôi chọn kỹ thuật … ở ô … vì…’. Tiêu chí Đạt: (1) cao độ và nhịp của melody đúng; (2) kỹ thuật nghe rõ, đúng bản chất; (3) giải thích có lý do âm nhạc.","required":true,"accepts":["video_link","text"]},{"kind":"study","tag":"Phần 2","title":"Phụ lục hiểu sâu — Melody và kỹ thuật","blocks":[{"b":"h","text":"Melody là gì"},{"b":"p","text":"Melody (giai điệu) là dòng nốt có cao độ và trường độ mà người nghe nhận ra như \"câu hát\". Trong Solo Guitar, melody thường nằm ở âm vực cao nhất của tiếng đàn; Bass và hợp âm nằm bên dưới. Các buổi sau thêm hai tầng đó dưới chính melody này."},{"b":"h","text":"Chùm ba (Triplet) trong bài"},{"b":"p","text":"Nhiều ô chia một phách thành ba nốt đều nhau. Cảm giác \"lắc nhẹ\" ấy là một phần màu sắc của bài. Khi thêm kỹ thuật, đừng làm mất nhịp lắc đó: luyến hay trượt trong chùm ba phải giữ ba nốt đều."},{"b":"h","text":"Ký hiệu thường gặp trên bản nhạc và TAB"},{"b":"table","rows":[["Kỹ thuật","Ký hiệu thường thấy","Ghi chú"],["Hammer-on / Pull-off","Dấu luyến (nối cong) giữa hai nốt, có thể kèm chữ H / P trên TAB","Hai nốt khác cao độ, cùng một dây"],["Slide","Gạch chéo giữa hai nốt","Một ngón, hai ngăn khác nhau, cùng một dây"],["Vibrato","Đường lượn sóng phía trên nốt","Thường đặt trên nốt dài"],["Bend","Mũi tên cong phía trên TAB, kèm số cung (½, 1…)","Có thể có Release (nhả về)"]]},{"b":"callout","label":"LƯU Ý CHUYÊN MÔN","text":"Kỹ thuật là LỰA CHỌN diễn tấu. Cùng một melody, hai người chơi có thể chọn hai bộ kỹ thuật khác nhau và cả hai đều đúng. Chỉ cao độ và trường độ mới \"đúng – sai\" theo bản nhạc."},{"b":"h","text":"Vibrato"},{"b":"p","text":"Có thể rung theo hướng song song với phím đàn hoặc vuông góc với phím đàn; người chơi chọn theo hợp thế tay. Quan trọng là rung ĐỀU và trở về đúng cao độ gốc."},{"b":"h","text":"Bend: hai điều dễ sai"},{"b":"ul","items":["Một cung = hai ngăn; nửa cung = một ngăn. Bend \"một cung\" nâng cao độ bằng hai ngăn.","Nên đàn nốt đích thật (ở ngăn khác) để tai nhớ cao độ trước khi tay đẩy dây."]},{"b":"callout","label":"CẦN OWNER XEM LẠI","text":"Bản nhạc chuẩn có cung nối (Tie) và cung luyến (Slur) nhưng không ghi kỹ thuật (Hammer-on, Pull-off, trượt, rung, bend). Mọi chỗ gắn kỹ thuật trong buổi này (ô 7, 8, 9, 18) là gợi ý của giáo án, chưa phải bản phối đã xác nhận; ở ô 7 và 9 gợi ý thay cho cung luyến của bản chuẩn."}]},{"kind":"assignment","items":[{"label":"Bài 1.","text":"Mỗi kỹ thuật ở bài tập riêng: 3 phút mỗi ngày, chậm, tiếng đều."},{"label":"Bài 2.","text":"Đàn ô 1–8 melody gốc (không kỹ thuật) cho sạch tiếng, tempo ♩ = 60."},{"label":"Bài 3.","text":"Thử cả bốn gợi ý ở các ô 7, 8, 9, 18 rồi chọn một; ghi \"Tôi chọn kỹ thuật này vì…\"."},{"label":"Bài 4.","text":"Tìm thêm ít nhất một chỗ trong ô 10–41 có thể thêm kỹ thuật, đánh dấu và giải thích."}],"message":"Hai bạn cùng lớp có thể chọn hai kỹ thuật khác nhau cho cùng một chỗ. Hãy mang lý do đến lớp."},{"kind":"checklist","items":["Tôi đàn đúng cao độ và trường độ ô 1–8.","Tôi phân biệt được Hammer-on, Pull-off, Slide, Vibrato, Bend.","Tôi biết vì sao nốt dây buông không rung được.","Tôi làm được ít nhất ba trong năm kỹ thuật cho sạch tiếng.","⭐ Tôi nói được vì sao mình chọn kỹ thuật đó ở chỗ đó."]},{"kind":"studentNotes","title":"Tôi chọn kỹ thuật này vì…","lines":8}]$j$::jsonb
   where session_id = '028adc12-051f-4d23-a514-d85a4aa064a2' and md5(blocks::text) = '2a0582d762d20a1710a5fad939250be6';
  get diagnostics n = row_count;
  if n <> 1 then raise exception 'Buổi 9: nội dung trên Class đã đổi so với lúc đọc (md5) — dừng, không ghi đè'; end if;
  -- Buổi 10
  update public.class_lesson_content set blocks = $j$[{"kind":"recap","title":"Từ Buổi 1 sang Buổi 2","steps":[{"label":"Buổi 1 đã có","items":["Melody ô 1–8 sạch tiếng.","Năm kỹ thuật: Hammer-on, Pull-off, Vibrato, Slide, Bend."]},{"label":"Buổi 2 thêm","items":["Tầng Bass nằm DƯỚI melody.","Chọn nốt Bass theo hợp âm, và chọn DÂY cho Bass để chừa chỗ cho hợp âm."]}],"message":"Vẫn Con Đường Xưa em Đi. Nguồn nhạc cho bạn melody và tên hợp âm; phần Bass chưa có — buổi này bạn học cách tự xác định và tự chọn."},{"kind":"objectives","title":"Cuối buổi, bạn làm được","items":["Phân biệt Root Note (nốt gốc của hợp âm) và Bass Note (nốt thấp nhất đang vang).","Biết vị trí các nốt Bass trên ba dây trầm (dây 6, 5, 4).","Kiểm được nốt Bass có nằm DƯỚI nốt thấp nhất của melody trong ô hay không.","Biết chọn dây cho Bass: dây 6–5, để chừa dây 4–2 cho hợp âm ở các buổi sau.","⭐ QUAN TRỌNG NHẤT — Tự chọn Bass cho ô 2–8 và nói được vì sao."]},{"kind":"note","title":"Nhịp 1 · Nốt gốc, Bass Note và bản đồ Bass","text":"Phần 1 — Làm ngay: tìm đủ các nốt Bass trên ba dây trầm, rồi đàn khung Bass gốc cho ô 2–8. Kết thúc nhịp: Bài trả 10.1 (trắc nghiệm)."},{"kind":"fretboard","title":"Phần 1 — Nốt Bass trên ba dây trầm","lead":"Dây 6 (E), dây 5 (A), dây 4 (D), bốn ngăn đầu. Chấm đậm là nốt dây buông. Nốt thấp nhất bạn đàn được trên guitar chuẩn là Mi dây 6 buông (E2).","frets":5,"zones":[{"no":1,"label":"Bass dây buông","tag":"","fromFret":0,"toFret":0,"strings":[1,6],"color":"#4338CA","hidden":true,"hint":"E · A · D buông."},{"no":2,"label":"Bass phải bấm","tag":"","fromFret":1,"toFret":5,"strings":[1,6],"color":"#A85F0E","hidden":true,"hint":"F · G · B · C."}],"dots":[{"string":6,"fret":0,"name":"E","nameVi":"Mi","zone":1,"root":true},{"string":6,"fret":1,"name":"F","nameVi":"Fa","zone":2,"root":false},{"string":6,"fret":3,"name":"G","nameVi":"Sol","zone":2,"root":false},{"string":5,"fret":0,"name":"A","nameVi":"La","zone":1,"root":true},{"string":5,"fret":2,"name":"B","nameVi":"Si","zone":2,"root":false},{"string":5,"fret":3,"name":"C","nameVi":"Đô","zone":2,"root":false},{"string":4,"fret":0,"name":"D","nameVi":"Rê","zone":1,"root":true},{"string":4,"fret":3,"name":"F","nameVi":"Fa","zone":2,"root":false},{"string":5,"fret":5,"name":"D","nameVi":"Rê","zone":2,"root":false}],"legend":["E · A · D buông: bass dễ nhất, vang nhất","F (dây 6 ngăn 1) · G (dây 6 ngăn 3): bass cho hợp âm F, G","Rê dây 5 ngăn 5 = cùng cao độ với Rê dây 4 buông: dùng khi muốn chừa dây 4 cho hợp âm","B (dây 5 ngăn 2) · C (dây 5 ngăn 3): bass cho hợp âm E7/E (quãng 5) và C"]},{"kind":"recap","title":"Root Note và Bass Note","steps":[{"label":"Root Note","items":["Nốt gốc: nốt đặt TÊN cho hợp âm.","Am → La · Dm → Rê · E → Mi · F → Fa · G → Sol · C → Đô."]},{"label":"Bass Note","items":["Nốt THẤP NHẤT đang vang.","Thường là Root Note, nhưng có thể là nốt khác của hợp âm."]},{"label":"Ký hiệu","items":["Am/E đọc \"Am trên Mi\": hợp âm Am, nốt Bass là Mi.","Khi Bass Note ≠ Root Note gọi là Chord Inversion (thể đảo) hoặc hợp âm có bass khác gốc."]}],"message":"Mọi hợp âm của bài (Am, Dm, E, E7, F, G, C) đều có nốt gốc nằm được trên ba dây trầm — nhưng \"nằm được\" chưa có nghĩa là \"nên đàn\" trong ô đó. Tiếp theo bạn sẽ thấy vì sao."},{"kind":"score","subtitle":"Phần 1 — Làm ngay","title":"Khung Bass gốc, ô 2–8 (mỗi ô một nốt tròn)","lead":"Chỉ ngón cái p. Nốt gốc theo đúng tên hợp âm trong MusicXML (ô 5 giữ hợp âm Am của ô 4). Đây là bản khung để nghe nền hòa âm, CHƯA ghép với melody.","tempo":"Tempo: ♩ = 60","tex":"\\ts 4 4\n.\n0.5{ch \"Am\"}.1 |\n0.4{ch \"Dm\"}.1 |\n0.5{ch \"Am\"}.1 |\n0.5.1 |\n0.4{ch \"Dm\"}.1 |\n0.5{ch \"Am\"}.1 |\n0.6{ch \"E\"}.1 |","guidance":["Ô 2, 4, 5, 7: La dây 5 buông. Ô 3, 6: Rê dây 4 buông. Ô 8: Mi dây 6 buông.","Đàn đều, mỗi nốt vang trọn 4 phách; nghe nền hòa âm đổi Am → Dm → Am → E.","⚠️ Ô 3 và 6: Rê dây 4 buông (D3) nằm trên DÂY 4 — dây sẽ dành cho hợp âm ở Buổi 4–6. Nhịp 2 sẽ xử lý chỗ này."]},{"kind":"checkpoint","id":"10.1","title":"Bài trả 10.1 — Root Note và Bass Note","required":true,"accepts":["quiz"],"quiz":{"mode":"single","question":"Ký hiệu Am/E cho biết điều gì?","options":[{"id":"a","text":"Hợp âm Am, với Mi là nốt thấp nhất (Bass Note)"},{"id":"b","text":"Hợp âm E, với La là nốt thấp nhất"},{"id":"c","text":"Đàn hợp âm Am rồi đàn hợp âm E"},{"id":"d","text":"Hợp âm Am nhưng bỏ nốt Mi"}],"hint":"Phần đứng TRƯỚC dấu gạch chéo là hợp âm; phần đứng SAU là nốt thấp nhất."}},{"kind":"note","title":"Nhịp 2 · Bass phải nằm dưới melody","text":"Kiểm từng ô: nốt Bass có thấp hơn nốt thấp nhất của melody không, và Bass có chiếm dây dành cho hợp âm không? Kết thúc nhịp: Bài trả 10.2 (trắc nghiệm)."},{"kind":"score","subtitle":"Cùng đoạn, đối chiếu","title":"Melody ô 2–8 (để so với khung Bass)","lead":"Nốt thấp nhất của melody trong từng ô: ô 2 Mi (dây 1 buông) · ô 3 Đô (dây 2 ngăn 1) · ô 4 Mi · ô 5 La (dây 3 ngăn 2) · ô 6 Đô (dây 2 ngăn 1) · ô 7 Mi · ô 8 Si (dây 1 ngăn 7).","tempo":"Tempo: ♩ = 60","tex":"\\ts 4 4\n.\n5.1{lf 2 ch \"Am\"}.4{d} 0.1.8 5.1{lf 2}.8 8.1{lf 5}.4 0.1.8 |\n3.2{lf 2 ch \"Dm\"}.4{d} 5.2{lf 4 slur s2}.16 3.2{lf 2 slur s2}.16 1.2{lf 2}.4{tu 3} 3.2{lf 2}.4{tu 3} 0.1{slur s3}.8{tu 3} 5.1{lf 4 slur s3}.8{tu 3} |\n0.1{ch \"Am\"}.1 |\n0.1{t}.4 0.1.4 2.3{lf 3}.4{tu 3} 1.2{lf 2 slur s4}.8{tu 3} 3.2{lf 4 slur s4}.8{tu 3} 3.2{lf 4}.4{tu 3} |\n3.2{lf 4 ch \"Dm\"}.4{d} 0.1.8 3.2{lf 4}.8 1.2{lf 2}.4 1.1{lf 2}.8 |\n0.1{ch \"Am\"}.4{d} 0.1{slur s5}.16 1.1{lf 2 slur s5}.16 0.1.4{tu 3} 5.1{lf 2}.4{tu 3} 8.1{lf 5}.4{tu 3} |\n7.1{lf 4 ch \"E\"}.1 |","guidance":["Bass phải THẤP HƠN nốt thấp nhất của melody trong ô, nếu không melody không còn là nốt cao nhất và nghe \"chìm\".","Bass trùng cao độ với nốt melody thì hai nốt hòa làm một — nghe mất một tầng."]},{"kind":"recap","title":"Bảng kiểm Bass cho ô 2–8","steps":[{"label":"Ô 2, 4, 7 · Am","items":["Melody thấp nhất: Mi (dây 1 buông, E4).","La dây 5 buông (A2) nằm dưới hơn một quãng 8 → DÙNG ĐƯỢC nốt gốc."]},{"label":"Ô 3, 6 · Dm","items":["Melody thấp nhất: Đô (dây 2 ngăn 1, C4).","Rê dây 4 buông (D3) thấp hơn nên dùng được, nhưng chiếm dây 4.","Ưu tiên Rê dây 5 ngăn 5 (cùng D3) để dây 4 trống; hoặc La dây 5 buông (Dm/A), Fa dây 6 ngăn 1 (Dm/F)."]},{"label":"Ô 5 · Am (tiếp)","items":["Melody thấp nhất: La (dây 3 ngăn 2, A3) — nốt thấp nhất của cả bài.","La dây 5 buông (A2) thấp hơn đúng một quãng 8: cùng tên nốt nhưng KHÔNG trùng cao độ → DÙNG ĐƯỢC."]},{"label":"Ô 8 · E","items":["Melody: Si (dây 1 ngăn 7, B4).","Mi dây 6 buông nằm dưới hơn hai quãng 8 → DÙNG ĐƯỢC nốt gốc."]}],"message":"Quy tắc: Bass thấp hơn melody, không trùng cao độ, và ở dây 6–5. Bản phối quãng 8 cao nên khoảng cách rộng, ít khi vi phạm. Nếu một lúc nào đó nốt gốc vi phạm, đổi sang nốt khác CỦA CHÍNH HỢP ÂM đó (quãng 5 hoặc quãng 3) nằm thấp hơn."},{"kind":"layers","title":"Cùng một đoạn, hai khung Bass","lead":"Cả hai khung đều đúng nốt gốc và đều nằm dưới melody. Khác nhau ở DÂY của nốt Rê (ô 3, 6): khung A dùng dây 4 buông, khung B dùng dây 5 ngăn 5 để chừa dây 4 cho hợp âm.","layers":[{"label":"Khung A","what":"Rê dây 4 buông — dễ, vang, nhưng chiếm dây 4.","tex":"\\ts 4 4\n.\n0.5{ch \"Am\"}.1 |\n0.4{ch \"Dm\"}.1 |\n0.5{ch \"Am\"}.1 |\n0.5.1 |\n0.4{ch \"Dm\"}.1 |\n0.5{ch \"Am\"}.1 |\n0.6{ch \"E\"}.1 |"},{"label":"Khung B","what":"Rê dây 5 ngăn 5 (cùng cao độ) — Bass trọn trên dây 6–5, dây 4–2 dành cho hợp âm.","tex":"\\ts 4 4\n.\n0.5{ch \"Am\"}.1 |\n5.5{ch \"Dm\"}.1 |\n0.5{ch \"Am\"}.1 |\n0.5.1 |\n5.5{ch \"Dm\"}.1 |\n0.5{ch \"Am\"}.1 |\n0.6{ch \"E\"}.1 |","current":true}],"note":"Khung B không phải đáp án duy nhất. Ô 3 và 6 còn có thể dùng La dây 5 buông (Dm/A) hoặc Fa dây 6 ngăn 1 (Dm/F). Chọn nốt nào, hãy nghe thử rồi giải thích."},{"kind":"checkpoint","id":"10.2","title":"Bài trả 10.2 — Bass và melody","required":true,"accepts":["quiz"],"quiz":{"mode":"single","question":"Ô 24 có hợp âm C, nốt thấp nhất của melody là Đô (dây 2 ngăn 1, C4). Nếu đàn Bass gốc Đô ở dây 5 ngăn 3 (C3) thì sao?","options":[{"id":"a","text":"Dùng được: hai nốt cùng tên Đô nhưng cách nhau một quãng 8, Bass vẫn thấp hơn melody và nằm ở dây 5, chừa dây 4–2 cho hợp âm"},{"id":"b","text":"Không dùng được: hai nốt cùng tên thì luôn trùng cao độ"},{"id":"c","text":"Phải bỏ hẳn Bass trong cả bài"},{"id":"d","text":"Phải đổi sang hợp âm khác"}],"hint":"Cao độ phụ thuộc cả quãng 8, không chỉ tên nốt. Đô thấp và Đô cao là hai cao độ khác nhau."}},{"kind":"note","title":"Nhịp 3 · Tự chọn Bass cho ô 2–8","text":"Tự điền nốt Bass từng ô theo bảng kiểm, nghe thử rồi giải thích. Kết thúc nhịp: Bài trả 10.3 (video + giải thích)."},{"kind":"repertoire","title":"Phần 2 (thực hành) — Điền Bass cho ô 2–8","candidates":["Con Đường Xưa em Đi — tự chọn Bass cho ô 2–8"],"status":"ready","pieces":[{"title":"Ô 2–8 — melody (Bass để trống có chủ ý)","composer":"Châu Kỳ & Hồ Đình Phương · giọng Am","note":"Bản này CHỈ có melody và tên hợp âm — Bass để trống. Nhìn tên hợp âm và bảng kiểm, viết nốt Bass (tên nốt + dây + ngăn) vào bản in.","barsPerRow":2,"tex":"\\ts 4 4\n.\n5.1{lf 2 ch \"Am\"}.4{d} 0.1.8 5.1{lf 2}.8 8.1{lf 5}.4 0.1.8 |\n3.2{lf 2 ch \"Dm\"}.4{d} 5.2{lf 4 slur s2}.16 3.2{lf 2 slur s2}.16 1.2{lf 2}.4{tu 3} 3.2{lf 2}.4{tu 3} 0.1{slur s3}.8{tu 3} 5.1{lf 4 slur s3}.8{tu 3} |\n0.1{ch \"Am\"}.1 |\n0.1{t}.4 0.1.4 2.3{lf 3}.4{tu 3} 1.2{lf 2 slur s4}.8{tu 3} 3.2{lf 4 slur s4}.8{tu 3} 3.2{lf 4}.4{tu 3} |\n3.2{lf 4 ch \"Dm\"}.4{d} 0.1.8 3.2{lf 4}.8 1.2{lf 2}.4 1.1{lf 2}.8 |\n0.1{ch \"Am\"}.4{d} 0.1{slur s5}.16 1.1{lf 2 slur s5}.16 0.1.4{tu 3} 5.1{lf 2}.4{tu 3} 8.1{lf 5}.4{tu 3} |\n7.1{lf 4 ch \"E\"}.1 |","guidance":["1. Ghi nốt gốc của hợp âm.","2. Tìm nốt thấp nhất của melody trong ô.","3. Nốt gốc có thấp hơn không? Có → dùng, ưu tiên dây 6–5. Không → đổi sang quãng 5 hoặc quãng 3 thấp hơn.","4. Đàn thử Bass với melody. Nghe còn rõ melody không?","5. Ghi lại: \"Tôi chọn Bass này vì…\""]}],"annotationTypes":["Nốt Bass bạn chọn","Dây · ngăn","Root hay đảo","Lý do chọn","Ghi chú của giáo viên"]},{"kind":"checkpoint","id":"10.3","title":"Bài trả 10.3 — Bass của tôi","prompt":"Chơi melody ô 2–5 kèm nốt Bass bạn đã chọn ở đầu mỗi ô (Bass gảy bằng ngón cái p). Không cần hoàn hảo. Sau đó viết ngắn: ‘Ở ô … tôi chọn Bass … vì…’. Tiêu chí Đạt: (1) Bass đúng tên hợp âm hoặc đúng thể đảo ghi rõ; (2) Bass nằm dưới melody, không trùng nốt; (3) giải thích dựa trên hợp âm và âm vực.","required":true,"accepts":["video_link","text"]},{"kind":"study","tag":"Phần 2","title":"Phụ lục hiểu sâu — Bass","blocks":[{"b":"h","text":"Nguyên tắc và lựa chọn"},{"b":"p","text":"Nguyên tắc hòa âm: nốt Bass nên thuộc hợp âm đang vang, và thường là nốt gốc khi không có lý do khác. Lựa chọn phối khí: dùng nốt gốc hay quãng 5, bass dây buông hay bass bấm, bass một nốt hay đi bước. Hai việc này khác nhau — nguyên tắc ít khi bị phá, còn lựa chọn thì mỗi người một cách."},{"b":"h","text":"Bảng nốt Bass của bài (từ tên hợp âm trong MusicXML)"},{"b":"table","rows":[["Hợp âm","Root Note","Bass gốc ở đâu","Quãng 5","Ghi chú"],["Am","La","dây 5 buông","Mi — dây 6 buông","bài chủ yếu ở Am"],["Dm","Rê","dây 5 ngăn 5 (hoặc dây 4 buông)","La — dây 5 buông","nên dùng dây 5 để chừa dây 4"],["E · E7","Mi","dây 6 buông","Si — dây 5 ngăn 2","E7 thêm Rê (quãng 7)"],["F","Fa","dây 6 ngăn 1","Đô — dây 5 ngăn 3","xem ô 32 bên dưới"],["G","Sol","dây 6 ngăn 3","Rê — dây 5 ngăn 5",""],["C","Đô","dây 5 ngăn 3","Sol — dây 6 ngăn 3","ô 24: Đô Bass (C3) và Đô melody (C4) cách một quãng 8"]]},{"b":"h","text":"Ba vùng dây"},{"b":"p","text":"Bản phối quãng 8 cao chia cần đàn thành ba vùng: Bass ở dây 6–5 (ngăn thấp), hợp âm ở dây 4–2 (ngăn trung đến cao), melody ở dây 1–2. Mỗi tầng một vùng nên không chồng lên nhau. Đó là lý do Bass nên tránh dây 4 khi có thể."},{"b":"h","text":"Vì sao Bass thấp hơn melody"},{"b":"p","text":"Tai người nghe giai điệu như nốt cao nhất trong một cụm. Khi Bass chen lên trên hoặc trùng melody, tai mất điểm tựa và bài nghe lẫn. Đó là lý do phần lớn bản Solo Guitar giữ melody làm nốt cao nhất và dành ba dây trầm cho Bass."},{"b":"h","text":"Thể đảo và Bass Note"},{"b":"p","text":"Khi Bass Note không phải nốt gốc, ta có hợp âm đảo (Chord Inversion), viết dạng X/Y. Ví dụ Dm/A: hợp âm Rê thứ với La ở thấp nhất. Thể đảo thường làm đường Bass đi mượt hơn và tránh va melody."},{"b":"callout","label":"CẦN OWNER XEM LẠI","text":"Hợp âm trong MusicXML là nguồn duy nhất; Bass, thể đảo và việc chọn dây (Bass dây 6–5) trong buổi này do giáo án đề xuất cho bản phối nâng một quãng 8. Ô 32 trong nguồn ghi hợp âm F nhưng giai điệu (Đô, Mi, La, Sol♯) giống Am → E; giữ nguyên nguồn, cần rà soát chuyên môn (không ảnh hưởng ô 2–8)."}]},{"kind":"assignment","items":[{"label":"Bài 1.","text":"Đàn khung Bass gốc ô 2–8 (chậm, đều, 5 phút mỗi ngày)."},{"label":"Bài 2.","text":"Điền nốt Bass cho ô 2–8 vào bản in, ghi rõ dây · ngăn, và thể đảo nếu có."},{"label":"Bài 3.","text":"Đàn melody ô 2–8 kèm Bass của bạn, nghe còn rõ melody không."},{"label":"Bài 4.","text":"Làm tương tự cho ô 18–21 (Am, F, G, C): tìm nốt thấp nhất của melody, rồi chọn Bass dưới nó."}],"message":"Bass của bạn có thể khác bạn bên cạnh. Mang lý do đến lớp, ta nghe từng phương án."},{"kind":"checklist","items":["Tôi phân biệt được Root Note và Bass Note.","Tôi tìm được các nốt Bass trên dây 6, 5, 4.","Tôi kiểm được Bass có nằm dưới melody không.","Tôi biết đổi sang quãng 5 hoặc quãng 3 khi nốt gốc không hợp.","⭐ Tôi nói được vì sao mình chọn Bass đó."]},{"kind":"studentNotes","title":"Tôi chọn Bass này vì…","lines":8}]$j$::jsonb
   where session_id = '0c1d496c-c9b3-49b1-bca7-d4537b0eee2d' and md5(blocks::text) = '1c30fae4b8736822fc4bc6cfbc6fd1cc';
  get diagnostics n = row_count;
  if n <> 1 then raise exception 'Buổi 10: nội dung trên Class đã đổi so với lúc đọc (md5) — dừng, không ghi đè'; end if;
  -- Buổi 11
  update public.class_lesson_content set blocks = $j$[{"kind":"recap","title":"Từ Buổi 2 sang Buổi 3","steps":[{"label":"Buổi 2 đã có","items":["Nốt Bass dưới melody.","Bass ở dây 6–5, chừa dây 4–2 cho hợp âm."]},{"label":"Buổi 3 thêm","items":["Xếp ngón tay trái cho cả câu melody.","Chọn vị trí (Position) và nhìn trước ngón kế tiếp."]}],"message":"Ở Chặng 1 bạn đã xếp ngón cho từng câu ngắn. Giờ ta nhìn cả bài: một bộ ngón sẽ còn phải chung sống với Bass và hợp âm ở các buổi sau."},{"kind":"objectives","title":"Cuối buổi, bạn làm được","items":["Hiểu khái niệm Vị trí (Position): ngón 1 ở ngăn nào thì gọi tên vị trí theo ngăn đó. Melody của bài dùng Vị trí I, III, V, VII và IX.","Áp dụng quy tắc một ngăn – một ngón TRONG MỘT VỊ TRÍ và biết khi nào phải đổi vị trí.","Nhìn trước ngón kế tiếp để tay trái không phải nhảy.","Nhận ra nốt cần giữ ngón (Guide Finger) khi chuyển hợp âm hoặc đổi vị trí.","⭐ QUAN TRỌNG NHẤT — Tự xếp ngón cho một câu và nói được vì sao."]},{"kind":"note","title":"Nhịp 1 · Vị trí (Position) và quy tắc một ngăn – một ngón","text":"Phần 1 — Làm ngay: đàn ô 1–8 theo ngón đã ghi trên bản nhạc. Kết thúc nhịp: Bài trả 11.1 (trắc nghiệm)."},{"kind":"score","subtitle":"Phần 1 — Làm ngay","title":"Ô 1–8 với ngón tay trái đã ghi","lead":"Mỗi vị trí phủ bốn ngăn liền nhau: ngón 1 giữ ngăn đầu, ngón 2 ngăn kế, ngón 3 ngăn kế nữa, ngón 4 ngăn cuối. Vị trí I phủ ngăn 1–4; Vị trí V phủ ngăn 5–8. Dây buông không ghi ngón. (Ngón 1 = trỏ, 2 = giữa, 3 = áp út, 4 = út.)","tempo":"Tempo: ♩ = 60","tex":"\\ts 4 4\n.\nr.4 0.1.4 1.2{lf 2}.4{tu 3} 3.1{lf 4 slur s1}.8{tu 3} 5.1{lf 2 slur s1}.8{tu 3} 5.1{lf 2}.4{tu 3} |\n5.1{lf 2 ch \"Am\"}.4{d} 0.1.8 5.1{lf 2}.8 8.1{lf 5}.4 0.1.8 |\n3.2{lf 2 ch \"Dm\"}.4{d} 5.2{lf 4 slur s2}.16 3.2{lf 2 slur s2}.16 1.2{lf 2}.4{tu 3} 3.2{lf 2}.4{tu 3} 0.1{slur s3}.8{tu 3} 5.1{lf 4 slur s3}.8{tu 3} |\n0.1{ch \"Am\"}.1 |\n0.1{t}.4 0.1.4 2.3{lf 3}.4{tu 3} 1.2{lf 2 slur s4}.8{tu 3} 3.2{lf 4 slur s4}.8{tu 3} 3.2{lf 4}.4{tu 3} |\n3.2{lf 4 ch \"Dm\"}.4{d} 0.1.8 3.2{lf 4}.8 1.2{lf 2}.4 1.1{lf 2}.8 |\n0.1{ch \"Am\"}.4{d} 0.1{slur s5}.16 1.1{lf 2 slur s5}.16 0.1.4{tu 3} 5.1{lf 2}.4{tu 3} 8.1{lf 5}.4{tu 3} |\n7.1{lf 4 ch \"E\"}.1 |","marks":[{"at":"Ô 1","text":"dịch từ Vị trí I (Đô dây 2 ngăn 1, Sol ngăn 3) lên Vị trí V (La ngăn 5)"},{"at":"Ô 3","text":"Vị trí III cho Rê và Mi (dây 2 ngăn 3 và ngăn 5; Mi → Rê luyến CÙNG dây), về Vị trí I cho Đô (ngăn 1), lại Vị trí III cho Rê, rồi La ngăn 5 bằng ngón 3"},{"at":"Ô 4","text":"nốt tròn Mi dây buông: tay trái hoàn toàn rảnh — chỗ dịch về Vị trí I"},{"at":"Ô 7","text":"Vị trí I (Mi → Fa) rồi dịch lên Vị trí V cho La – Đô trong chùm ba cuối ô"}],"guidance":["Trong một vị trí, mỗi ngón \"sở hữu\" một ngăn: tay trái không phải nhảy.","Đổi vị trí ở chỗ có dây buông hoặc nốt dài; nhìn trước để biết sắp dịch.","Đặt ngón xuống ngay khi cần, nhấc ngay khi xong — không giữ thừa.","Nghe: nốt nào bị đứt tiếng vì nhấc ngón sớm? Nốt nào bị chồng tiếng vì nhấc trễ?"]},{"kind":"recap","title":"Bốn khái niệm cần nhớ","steps":[{"label":"Vị trí (Position)","items":["Gọi theo ngăn mà ngón 1 đang ở.","Vị trí I: ngón 1 ở ngăn 1, phủ ngăn 1–4. Vị trí V: ngón 1 ở ngăn 5, phủ ngăn 5–8."]},{"label":"Một ngăn – một ngón","items":["Trong một vị trí: ngăn đầu → ngón 1, ngăn kế → ngón 2, rồi ngón 3, ngón 4.","Là quy tắc mặc định; phá quy tắc khi có lý do (nối nốt, chuẩn bị ngón)."]},{"label":"Giữ ngón (Guide Finger)","items":["Ngón nằm yên trên dây khi các nốt kế tiếp vẫn cần nó.","Làm tay trái ít di chuyển và tiếng nối mượt."]},{"label":"Đổi vị trí (Position Shift)","items":["Dịch cả bàn tay lên hoặc xuống cần đàn.","Làm ở dây buông, nốt dài, hoặc bằng ngón dẫn trượt sang nốt mới."]}],"message":"Giai điệu của bài (bản phối quãng 8 cao) trải từ ngăn 1 đến ngăn 12 trên dây 1–2, nên phải đổi vị trí nhiều lần. Đó là lý do bài hợp để học xếp ngón."},{"kind":"checkpoint","id":"11.1","title":"Bài trả 11.1 — Vị trí và quy tắc ngón","required":true,"accepts":["quiz"],"quiz":{"mode":"single","question":"Theo quy tắc một ngăn – một ngón ở Vị trí I, một nốt bấm ở ngăn 3 nên dùng ngón nào?","options":[{"id":"a","text":"Ngón 1 (trỏ)"},{"id":"b","text":"Ngón 2 (giữa)"},{"id":"c","text":"Ngón 3 (áp út)"},{"id":"d","text":"Ngón 4 (út)"}],"hint":"Ở Vị trí I, ngón nào đứng ở ngăn nào thì số ngón bằng số ngăn."}},{"kind":"note","title":"Nhịp 2 · Nhìn cả câu: điệp khúc và chuyển hợp âm","text":"Đàn đoạn dài hơn (ô 18–25), nhìn trước ngón kế tiếp, tìm chỗ cần giữ ngón và chỗ đổi vị trí. Kết thúc nhịp: Bài trả 11.2 (trắc nghiệm)."},{"kind":"layers","title":"Ô 18–19: cùng đoạn, có và chưa có ngón","lead":"Hai ô đầu điệp khúc nhảy giữa nốt thấp và nốt cao trên dây 1: La (ngăn 5), Mi (ngăn 12), Rê (ngăn 10), Đô (ngăn 8). Nhìn ngón giúp tay trái biết trước chỗ cần đến.","layers":[{"label":"Chưa ghi ngón","what":"Chỉ có nốt — bạn tự chọn ngón mỗi lần đàn, dễ lúng túng khi nhảy từ ngăn 5 lên ngăn 12.","tex":"\\ts 4 4\n.\n5.1{ch \"Am\"}.2 5.1.4{tu 3} 12.1.4{tu 3} 10.1.4{tu 3} |\n8.1{ch \"F\"}.2 5.1.4{tu 3} 10.1.4{tu 3} 8.1.4{tu 3} |"},{"label":"Có ngón","what":"Ô 18: Vị trí V cho La (ngăn 5, ngón 1), rồi Vị trí IX cho Mi (ngăn 12, ngón 4) và Rê (ngăn 10, ngón 2). Ô 19: Vị trí V cho Đô và La, rồi Vị trí VII cho Rê (ngón 4) và Đô (ngón 2).","tex":"\\ts 4 4\n.\n5.1{lf 2 ch \"Am\"}.2 5.1{lf 2}.4{tu 3} 12.1{lf 5}.4{tu 3} 10.1{lf 3}.4{tu 3} |\n8.1{lf 5 ch \"F\"}.2 5.1{lf 2}.4{tu 3} 10.1{lf 5}.4{tu 3} 8.1{lf 3}.4{tu 3} |","current":true}],"note":"Hai ô này đi qua ba vùng: Vị trí V, IX và VII. Không có dây buông để nghỉ, nên dịch tay bằng ngón dẫn: ngón vừa đàn nốt cũ đi trước, các ngón khác theo sau."},{"kind":"score","subtitle":"Thực hành","title":"Điệp khúc nửa đầu: ô 18–25","lead":"Am – F – G – C – Am – Dm – C – Am. Chú ý: ô 20 mở đầu bằng Sol (dây 1 ngăn 3); ô 21 mở bằng Mi dây 1 buông và có một phách nghỉ — dùng để chuẩn bị ngón.","tempo":"Tempo: ♩ = 60","tex":"\\ts 4 4\n.\n5.1{lf 2 ch \"Am\"}.2 5.1{lf 2}.4{tu 3} 12.1{lf 5}.4{tu 3} 10.1{lf 3}.4{tu 3} |\n8.1{lf 5 ch \"F\"}.2 5.1{lf 2}.4{tu 3} 10.1{lf 5}.4{tu 3} 8.1{lf 3}.4{tu 3} |\n3.1{lf 2 ch \"G\"}.4{d} 3.1{lf 2}.8 3.1{lf 2}.4{tu 3} 5.1{lf 2}.4{tu 3} 8.1{lf 5}.4{tu 3} |\n0.1{ch \"C\"}.2 r.4 0.1.4 |\n0.1{ch \"Am\"}.2 0.1.4{tu 3} 5.1{lf 2}.4{tu 3} 0.1.4{tu 3} |\n3.2{lf 4 ch \"Dm\"}.2 3.2{lf 4}.4{tu 3} 0.1.4{tu 3} 3.2{lf 4}.4{tu 3} |\n1.2{lf 2 ch \"C\"}.4{d} 1.2{lf 2}.8 1.2{lf 2}.8 1.1{lf 2}.4 0.1.8 |\n2.3{lf 3 ch \"Am\"}.2 r.4 5.1{lf 2}.4 |","marks":[{"at":"Ô 18–19","text":"nhảy giữa ngăn 5, 8, 10, 12 trên dây 1: Vị trí V → IX → V → VII"},{"at":"Ô 21","text":"Mi buông và phách nghỉ: tay rảnh, chuẩn bị Vị trí V cho ô 22"},{"at":"Ô 24","text":"Đô (dây 2 ngăn 1) lặp ba lần rồi Fa (dây 1 ngăn 1) — cùng một ngón 1 chuyển từ dây 2 sang dây 1"}],"guidance":["Tìm những chỗ cùng một ngón phải đi từ dây này sang dây khác (ô 24): ngón 1 chuyển lên dây 1, đừng nhấc quá cao.","Tìm chỗ nhấc ngón hoặc dịch vị trí sớm: dây buông (ô 21) là lúc tay trái được nghỉ.","Chưa cần nhanh. Đàn chậm cho đến khi tay trái không \"nhảy\"."]},{"kind":"checkpoint","id":"11.2","title":"Bài trả 11.2 — Nhìn trước ngón","required":true,"accepts":["quiz"],"quiz":{"mode":"single","question":"Trong lúc đàn một nốt dây buông, tay trái được rảnh. Cách dùng khoảng rảnh đó tốt nhất là gì?","options":[{"id":"a","text":"Đặt sẵn ngón cho nốt kế tiếp"},{"id":"b","text":"Nhấc toàn bộ tay trái ra khỏi cần đàn"},{"id":"c","text":"Giữ nguyên ngón cũ cho đến hết ô"},{"id":"d","text":"Không làm gì, chờ nốt tới rồi mới đặt ngón"}],"hint":"Đây là ý \"nhìn trước\": ngón hôm nay chuẩn bị cho nốt tiếp theo."}},{"kind":"note","title":"Nhịp 3 · Tự xếp ngón và giải thích","text":"Xếp ngón cho ô 18–19 (hoặc đoạn bạn chọn) theo ý mình, đàn và thu video. Kết thúc nhịp: Bài trả 11.3 (video + giải thích)."},{"kind":"repertoire","title":"Phần thực hành — xếp ngón của bạn","candidates":["Con Đường Xưa em Đi — tự xếp ngón cho một câu"],"status":"ready","pieces":[{"title":"Ô 18–19 — chưa ghi ngón","composer":"Châu Kỳ & Hồ Đình Phương · giọng Am","note":"Bản này chưa ghi ngón. Bạn có thể giữ phương án mặc định hoặc đổi, miễn nói được vì sao.","barsPerRow":2,"tex":"\\ts 4 4\n.\n5.1{ch \"Am\"}.2 5.1.4{tu 3} 12.1.4{tu 3} 10.1.4{tu 3} |\n8.1{ch \"F\"}.2 5.1.4{tu 3} 10.1.4{tu 3} 8.1.4{tu 3} |","guidance":["1. Nhìn cả câu: nốt thấp nhất và cao nhất ở ngăn nào?","2. Chọn vị trí giữ tay (một vị trí có đủ không, hay phải đổi vị trí?).","3. Ghi ngón cho từng nốt.","4. Đàn thử: chỗ nào tay trái phải nhảy hoặc nhấc quá cao?","5. Sửa và ghi: \"Tôi xếp ngón này vì…\""]},{"title":"Ô 34–41 — đoạn kết (đã ghi ngón mặc định)","composer":"Châu Kỳ & Hồ Đình Phương · giọng Am","note":"Đoạn kết đi lại giữa Vị trí I, III và V. Đàn với ngón mặc định, đổi chỗ nào bạn thấy thuận hơn.","barsPerRow":2,"tex":"\\ts 4 4\n.\n5.1{lf 2 ch \"Am\"}.4{d} 0.1.8 5.1{lf 2}.8 8.1{lf 5}.4 0.1.8 |\n3.2{lf 2 ch \"Dm\"}.4{d} 5.2{lf 4 slur s12}.16 3.2{lf 2 slur s12}.16 1.2{lf 2}.4{tu 3} 3.2{lf 2}.4{tu 3} 0.1{slur s13}.8{tu 3} 5.1{lf 4 slur s13}.8{tu 3} |\n0.1{ch \"Am\"}.1 |\n0.1{t}.4 0.1.4 2.3{lf 3}.4{tu 3} 1.2{lf 2 slur s14}.8{tu 3} 3.2{lf 4 slur s14}.8{tu 3} 3.2{lf 4}.4{tu 3} |\n3.2{lf 4 ch \"Dm\"}.4{d} 0.1.8 3.2{lf 4}.8 1.2{lf 2}.4 1.1{lf 2}.8 |\n0.1{ch \"E\"}.4{d} 0.1{slur s15}.16 1.1{lf 2 slur s15}.16 0.1.4{tu 3} 3.1{lf 4}.4{tu 3} 7.1{lf 4}.4{tu 3} |\n5.1{lf 2 ch \"Am\"}.1 |\n5.1{t}.4 r.4 r.2"}],"annotationTypes":["Ngón tay trái","Vị trí","Chỗ giữ ngón","Lý do chọn","Ghi chú của giáo viên"]},{"kind":"checkpoint","id":"11.3","title":"Bài trả 11.3 — Xếp ngón của tôi","prompt":"Chơi ô 18–19 Con Đường Xưa em Đi theo cách xếp ngón của bạn (quay rõ tay trái nếu được). Không cần hoàn hảo. Viết ngắn: ‘Tôi xếp ngón … ở chỗ … vì…’. Tiêu chí Đạt: (1) ngón đúng với nốt (không ngăn nào dùng ngón làm hỏng cao độ); (2) tay trái không nhảy và không nhấc quá cao; (3) giải thích có lý do về vị trí hoặc ngón kế tiếp.","required":true,"accepts":["video_link","text"]},{"kind":"study","tag":"Phần 2","title":"Phụ lục hiểu sâu — Xếp ngón","blocks":[{"b":"h","text":"Ba nguyên tắc chọn ngón"},{"b":"ol","items":["Tiết kiệm di chuyển: chọn bộ ngón sao cho tay trái đi quãng ngắn nhất.","Nhìn trước: ngón của nốt hiện tại giúp ngón của nốt kế tiếp đến chỗ sớm.","Giữ ngón khi có thể: ngón nào còn cần ở nốt kế thì để yên trên dây."]},{"b":"h","text":"Cùng một nốt có thể bấm ở nhiều chỗ"},{"b":"p","text":"Trên guitar, cùng một cao độ thường có hai hoặc ba chỗ bấm. Ví dụ La4 (nốt hay gặp của bài) có thể là dây 1 ngăn 5, dây 2 ngăn 10 hoặc dây 3 ngăn 14. Bản phối này ưu tiên dây 1 (dây 2 khi nốt thấp): cùng một dây thì luyến và trượt tự nhiên, và dây 6–2 bên dưới còn trống cho Bass và hợp âm. Mi4 có thể là dây 1 buông (tay trái rảnh) hoặc dây 2 ngăn 5 (nếu muốn giữ tay ở Vị trí V)."},{"b":"h","text":"Xếp ngón và hợp âm sắp tới"},{"b":"p","text":"Sang Buổi 4–6 bạn sẽ thêm hợp âm dưới melody ở ngăn cao. Thế Am xx755x dùng ngón 1 ép ngăn 5 trên dây 3 và dây 2, ngón 3 ở ngăn 7 dây 4. Khi melody là La dây 1 ngăn 5 (ngón 1 ở Vị trí V), chính ngón 1 đó ép luôn dây 1: tay trái thành thế xx7555, một ngón ép ba dây. Đó là lý do nhiều nốt La được xếp ngón 1: xếp ngón của melody và của hợp âm hỗ trợ nhau. Vẫn có thể phải điều chỉnh khi ghép."},{"b":"h","text":"Đổi vị trí (Position Shift)"},{"b":"p","text":"Ba cách dịch tay: (1) ở dây buông hoặc phách nghỉ, khi tay trái rảnh; (2) trượt bằng ngón dẫn — ngón vừa đàn nốt cũ trượt sang nốt mới rồi cả bàn tay theo; (3) trong lúc một nốt dài còn vang. Tránh dịch xa giữa hai nốt liền nhau không có chỗ thở."},{"b":"callout","label":"LƯU Ý CHUYÊN MÔN","text":"Không có phương án xếp ngón \"duy nhất đúng\". Tiêu chí là: đúng cao độ, tay trái thoải mái, ghép được với các tầng khác. Phương án mặc định trong giáo án chỉ là điểm xuất phát."},{"b":"callout","label":"CẦN OWNER XEM LẠI","text":"Phương án ngón trong giáo án chọn các vị trí I · III · V · VII · IX sao cho ít lần đổi vị trí nhất cho cả bài, rồi gán ngón theo một ngăn – một ngón trong từng vị trí (tự động); chưa được người chơi kiểm từng ô. Ô 32 trong nguồn ghi hợp âm F nhưng giai điệu giống Am → E; giữ nguyên nguồn, cần rà soát chuyên môn."}]},{"kind":"assignment","items":[{"label":"Bài 1.","text":"Đàn ô 1–8 và ô 18–25 theo ngón đã ghi, chậm, 5 phút mỗi ngày."},{"label":"Bài 2.","text":"Đánh dấu trên bản in những chỗ tay trái phải nhảy xa hoặc nhấc ngón quá cao."},{"label":"Bài 3.","text":"Xếp lại ngón cho ô 18–19 theo ý bạn, ghi \"Tôi xếp ngón này vì…\"."},{"label":"Bài 4.","text":"Tự xếp ngón cho ô 34–41 (đoạn kết) và so với phương án mặc định."}],"message":"Hai bạn có thể xếp ngón khác nhau cho cùng một câu. Mang lý do đến lớp."},{"kind":"checklist","items":["Tôi giải thích được Vị trí (Position) và biết đổi vị trí khi cần.","Tôi áp dụng được quy tắc một ngăn – một ngón.","Tôi nhìn trước ngón kế tiếp ở những chỗ đổi dây.","Tôi biết chỗ nào nên giữ ngón.","⭐ Tôi nói được vì sao mình xếp ngón như vậy."]},{"kind":"studentNotes","title":"Tôi xếp ngón này vì…","lines":8}]$j$::jsonb
   where session_id = '14dd9919-5da6-46f1-9772-298833677d8b' and md5(blocks::text) = '9cec63047b36eecc17ae0851fbfe1374';
